import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './ws/messageHandler.js';
import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../types/session.js';
import type {SessionStore} from '../types/sessionStore.js';

describe('conversation list message handling', () => {
  it('forwards the composite cursor unchanged to the authenticated user’s store query', async () => {
    const before = {sessionId: 'cursor-1', updatedAt: '2026-01-02T00:00:00.000Z'};
    const listFor = jest.fn(() => []);
    const sent: unknown[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw))} as unknown as WebSocket;

    await createMessageHandler({} as ChatOrchestrator, {listFor} as unknown as SessionStore, {
      history: {enabled: true},
    })(ws, {sessionId: 's1', userId: 'u1', entries: []} as ChatSession, {
      type: 'list_conversations',
      before,
    });

    expect(listFor).toHaveBeenCalledWith('u1', {limit: undefined, before});
    expect(sent).toEqual([{type: 'conversation_list', conversations: []}]);
  });

  it('returns UNSUPPORTED when history listing is disabled or the store cannot list', async () => {
    const session = {sessionId: 's1', userId: 'u1', entries: []} as ChatSession;
    const enabledSent: unknown[] = [];
    const enabledSocket = {send: (raw: string) => enabledSent.push(JSON.parse(raw))} as unknown as WebSocket;
    const listFor = jest.fn(() => []);
    const store = {listFor} as unknown as SessionStore;
    const createHandler = createMessageHandler;

    await createHandler({} as ChatOrchestrator, store, {history: {enabled: false}})(enabledSocket, session, {
      type: 'list_conversations',
    });

    const unavailableSent: unknown[] = [];
    const unavailableSocket = {send: (raw: string) => unavailableSent.push(JSON.parse(raw))} as unknown as WebSocket;
    await createHandler({} as ChatOrchestrator, {} as SessionStore, {history: {enabled: true}})(
      unavailableSocket,
      session,
      {
        type: 'list_conversations',
      }
    );

    const callCount = listFor.mock.calls.length;
    expect({disabled: enabledSent, unavailable: unavailableSent, calls: callCount}).toEqual({
      disabled: [{type: 'error', code: 'UNSUPPORTED', message: 'Conversation listing is not enabled'}],
      unavailable: [{type: 'error', code: 'UNSUPPORTED', message: 'Conversation listing is not supported'}],
      calls: 0,
    });
  });

  it('answers list_conversations with the authenticated user’s summaries and ISO dates', async () => {
    const summary = {
      sessionId: 's2',
      createdAt: new Date('2026-01-01T00:00:00.000Z'),
      updatedAt: new Date('2026-01-02T00:00:00.000Z'),
      entryCount: 2,
    };
    let listedUserId: string | number | undefined;
    let listedOptions: {limit?: number; before?: unknown} | undefined;
    const listFor = jest.fn((userId: string | number, options?: {limit?: number; before?: unknown}) => {
      listedUserId = userId;
      listedOptions = options;
      return [summary];
    });
    const sessionStore = {listFor} as unknown as SessionStore;
    const sent: unknown[] = [];
    const ws = {
      send(raw: string) {
        sent.push(JSON.parse(raw));
      },
    } as unknown as WebSocket;
    const session = {sessionId: 's1', userId: 'u1', entries: []} satisfies ChatSession;

    await createMessageHandler({} as ChatOrchestrator, sessionStore, {history: {enabled: true}})(ws, session, {
      type: 'list_conversations',
      limit: 5,
      userId: 'u2',
    });

    expect({listedUserId, listedOptions, sent}).toEqual({
      listedUserId: 'u1',
      listedOptions: {limit: 5, before: undefined},
      sent: [
        {
          type: 'conversation_list',
          conversations: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-02T00:00:00.000Z',
              entryCount: 2,
            },
          ],
        },
      ],
    });
  });
});
